export function getBlogBySlug(slug: string): BlogPost | undefined {
  return blogPosts.find(b => b.slug === slug);
}

// Import anniversary blogs for primary display
import { anniversaryBlogPosts } from './anniversary-blogs';

export function getAllBlogPosts(): BlogPost[] {
  // Combine anniversary blogs with other blogs, prioritizing anniversary content
  const allBlogs = [...anniversaryBlogPosts, ...blogPosts.filter(b => b.category === 'Anniversary')];
  // Remove duplicates by slug
  const uniqueBlogs = allBlogs.filter((blog, index, self) => 
    index === self.findIndex(b => b.slug === blog.slug)
  );
  return uniqueBlogs.sort((a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime());
}

export function getBlogsByCategory(category: string): BlogPost[] {
  const allBlogs = [...anniversaryBlogPosts, ...blogPosts];
  return allBlogs.filter(b => b.category === category);
}
